from __future__ import annotations

from fastapi import APIRouter

from app.schemas.claims import (
    ClaimAdjudicationRequest,
    ClaimAdjudicationResponse,
    DisputeRequest,
    StoredClaimResponse,
)
from app.services import claims_service

router = APIRouter(prefix="/api/claims", tags=["claims"])


@router.post("/adjudicate", response_model=ClaimAdjudicationResponse)
def adjudicate(request: ClaimAdjudicationRequest) -> ClaimAdjudicationResponse:
    """Adjudicate a claim's line items without storing anything (stateless)."""
    return claims_service.adjudicate_claim_request(request)


@router.post("", response_model=StoredClaimResponse, status_code=201)
def create_claim(request: ClaimAdjudicationRequest) -> StoredClaimResponse:
    """Adjudicate and store a claim, returning its id and lifecycle state."""
    return claims_service.create_claim(request)


@router.get("", response_model=list[StoredClaimResponse])
def list_claims() -> list[StoredClaimResponse]:
    """List all stored claims."""
    return claims_service.list_claims()


@router.get("/{claim_id}", response_model=StoredClaimResponse)
def get_claim(claim_id: str) -> StoredClaimResponse:
    """Fetch a stored claim with its decisions and current state."""
    return claims_service.get_claim(claim_id)


@router.post("/{claim_id}/pay", response_model=StoredClaimResponse)
def pay_claim(claim_id: str) -> StoredClaimResponse:
    """Mark an approved / partially approved claim as paid."""
    return claims_service.pay_claim(claim_id)


@router.post("/{claim_id}/disputes", response_model=StoredClaimResponse)
def dispute_claim(claim_id: str, request: DisputeRequest) -> StoredClaimResponse:
    """Member disputes a decided claim, moving it to the disputed state."""
    return claims_service.dispute_claim(claim_id, request.reason)

