"""Supabase-backed claims repository.

Talks to Supabase's REST API (PostgREST) over httpx — no extra dependency and no
ORM. The whole claim is stored in one JSONB column (`data`); the (de)serialization
is pure and unit-tested separately from the network calls.

Requires the service-role key (the backend bypasses RLS). Selected only when
CLAIMS_BACKEND=supabase; the default backend stays in-memory.
"""

from __future__ import annotations

from decimal import Decimal
from typing import Any

import httpx

from app.domain.adjudication import (
    AdjudicatedLineItem,
    ClaimAdjudication,
    ClaimStatus,
    Decision,
    LineItem,
    Outcome,
    ReasonCode,
)
from app.domain.errors import ClaimNotFoundError
from app.domain.lifecycle import ClaimState
from app.repositories.claims_repository import StoredClaim


# --- Pure (de)serialization ----------------------------------------------

def _decision_to_dict(d: Decision) -> dict[str, Any]:
    return {
        "outcome": d.outcome.value,
        "payable_amount": str(d.payable_amount),
        "reason_code": d.reason_code.value,
        "reason_text": d.reason_text,
        "deductible_applied": str(d.deductible_applied),
    }


def claim_to_data(claim: StoredClaim) -> dict[str, Any]:
    return {
        "state": claim.state.value,
        "state_history": [s.value for s in claim.state_history],
        "dispute_reason": claim.dispute_reason,
        "line_items": [
            {"service_type": li.service_type, "billed_amount": str(li.billed_amount)}
            for li in claim.line_items
        ],
        "adjudication": {
            "claim_status": claim.adjudication.claim_status.value,
            "total_billed": str(claim.adjudication.total_billed),
            "total_payable": str(claim.adjudication.total_payable),
            "line_items": [
                {
                    "service_type": ali.service_type,
                    "billed_amount": str(ali.billed_amount),
                    "decision": _decision_to_dict(ali.decision),
                }
                for ali in claim.adjudication.line_items
            ],
        },
    }


def _decision_from_dict(d: dict[str, Any]) -> Decision:
    return Decision(
        outcome=Outcome(d["outcome"]),
        payable_amount=Decimal(d["payable_amount"]),
        reason_code=ReasonCode(d["reason_code"]),
        reason_text=d["reason_text"],
        deductible_applied=Decimal(d["deductible_applied"]),
    )


def claim_from_data(claim_id: str, data: dict[str, Any]) -> StoredClaim:
    adj = data["adjudication"]
    adjudication = ClaimAdjudication(
        claim_status=ClaimStatus(adj["claim_status"]),
        total_billed=Decimal(adj["total_billed"]),
        total_payable=Decimal(adj["total_payable"]),
        line_items=tuple(
